def get_bge_embedding(text_str: str) -> list[float]:
    payload = json.dumps({
        "model": "bge-m3:latest",
        "prompt": text_str[:4000]
    }).encode("utf-8")
    req = urllib.request.Request(
        OLLAMA_EMBED_URL,
        data=payload,
        headers={"Content-Type": "application/json"}
    )
    with urllib.request.urlopen(req, timeout=90) as resp:
        return json.loads(resp.read().decode("utf-8"))["embedding"]

DOSSIERS = [{'slug': 'text-silappadikaram-betel-paan-and-hospitality-poetry', 'category': 'texts', 'file': 'text-silappadikaram-betel-paan-and-hospitality-poetry.md', 'node_type': 'text', 'name_en': 'Silappadikaram Betel Leaf (Vetrillai), Areca Nut (Pakku) & Sangam Hospitality Hymns', 'name_ta': 'சிலப்பதிகாரம் - வெற்றிலை, பாக்கு மற்றும் சங்ககால விருந்தோம்பல் கவிதைகள்', 'era': 'Sangam to Post-Sangam Era', 'year_start': -100, 'year_end': 300, 'thinai': 'marutham', 'summary_en': 'Classical verses in Silappadikaram (Adaikkalakkadhai and Kolaikkalakkadhai) and Akananuru describing lush Kaveri delta betel gardens, royal paan hospitality, fragrance rolls spiced with nutmeg and cardamom, and gold-encrusted betel caskets.', 'summary_ta': 'சிலப்பதிகாரம் மற்றும் அகநானூற்றில் மருத நிலத்து வெற்றிலைக் கொடிக்கால்கள், பாக்குத் தோட்டங்கள், ஏலம்-ஜாதிக்காய் மணக்கும் தாம்பூல சுருள்கள் மற்றும் அரச விருந்தோம்பலின் சிறப்பைப் பாடும் பாடல்கள்.', 'sources': ['Silappadikaram Adaikkalakkadhai ll. 110-125', 'Akananuru v. 136', 'Manimekalai ll. 80-92'], 'content': '# Silappadikaram: Betel Leaf (Vetrillai), Areca Nut (Pakku) & Sangam Hospitality Hymns\n\n## 1. Classical Literary Evidence & Cultural Ethos\nIn the Sangam and post-Sangam Tamil canon, the offering of betel leaf (*Vetrillai*) and areca nut (*Pakku*) represented the supreme symbol of auspiciousness, royal hospitality, and emotional affinity. In Ilango Adigal’s *Silappadikaram* (Adaikkalakkadhai lines 110–125), the bustling street markets of Madurai and Poompuhar feature specialized vendors (*Vetrillai-pakku-virpor*) presenting freshly picked emerald betel leaves layered with mineral lime and fragrant mountain spices.\n\nSangam poetry describes the meticulous compounding of the paan roll (*Tamboolam* / *Surul*), perfumed with grated nutmeg (*Jathikkai*), cardamom (*Elam*), and cloves (*Kirambu*), serving as a diplomatic icebreaker and civic pledge.\n\n## 2. Agrarian & Societal Status\n- **Trellis Microclimate**: Betel vines were grown in shaded riverine gardens (*Kodik-kal*) supported on nitrogen-fixing sesbania trees (*Agathi*), demanding perennial freshwater drainage.\n- **Liturgical Sanctity**: No temple puja, royal coronation, marriage covenant (*Nichayathartham*), or treaty in ancient Tamilakam was ratified without exchanging betel rolls on cast bronze platters.\n'}, {'slug': 'insc-thiruvaduthurai-chola-betel-garden-endowments', 'category': 'inscriptions', 'file': 'insc-thiruvaduthurai-chola-betel-garden-endowments.md', 'node_type': 'inscription', 'name_en': 'Thiruvaduthurai Imperial Chola Betel Garden Tithes & Temple Paan Charters', 'name_ta': 'திருவாவடுதுறை - சோழர் வெற்றிலைக் கொடிக்கால் வரி மற்றும் தாம்பூல அறக்கொடை சாசனங்கள்', 'era': 'Medieval Chola Era', 'year_start': 950, 'year_end': 1150, 'thinai': 'marutham', 'summary_en': 'Imperial Chola epigraphs at the Gomuktisvara temple in Thiruvaduthurai detailing royal land grants for temple betel gardens (Vetrilaik-kodik-kal), daily allocations of seasoned leaves and areca nuts for deities, and guild tax exemptions.', 'summary_ta': 'திருவாவடுதுறை கோமுக்தீஸ்வரர் கோயில் கல்வெட்டுகள்; இறைவனுக்கு நாள்தோறும் தாம்பூலம் படைக்க வெற்றிலைக் கொடிக்கால்கள் அமைத்து நிலக்கொடை வழங்கிய சோழர் காலப் பதிவுகள்.', 'sources': ['South Indian Inscriptions Vol V (Thiruvaduthurai)', 'Epigraphia Indica Vol XXVIII', 'Chola Inscriptions on Temple Horticulture'], 'content': '# Thiruvaduthurai Imperial Chola Betel Garden Tithes & Temple Paan Charters\n\n## 1. Epigraphic Horizon & Garden Grants\nThe stone walls of the Thiruvaduthurai temple (Mayiladuthurai district, Kaveri delta) preserve vital Chola epigraphic records regarding state-sponsored horticulture. Inscriptions dating from Parantaka I to Rajendra Chola I formally deed fertile wetland parcels exclusively for cultivating betel vines (*Vetrilaik-kodi*) to maintain the daily ritual requirements of the temple.\n\n## 2. Liturgical Allocations & Quality Mandates\n- **Daily Leaf Quotas**: The charters mandate the daily supply of 100 to 200 prime, tender betel leaves (*Ilan-thalir*) alongside precisely weighed measures of split sun-cured areca nut (*Kottai-pakku*).\n- **Tax Concessions (*Kodik-kal-irai*)**: Royal tax officers were prohibited from levying the commercial garden tax (*Kodik-kal-irai*) on these sacred plots, ensuring uninterrupted harvest yields.\n'}, {'slug': 'insc-authoor-pandya-vetrillai-tax-and-trade-charters', 'category': 'inscriptions', 'file': 'insc-authoor-pandya-vetrillai-tax-and-trade-charters.md', 'node_type': 'inscription', 'name_en': 'Authoor Tambraparni Delta Betel Leaf Concessions & Riverine Trade Charters', 'name_ta': 'ஆத்தூர் - தாமிரபரணி படுகை வெற்றிலை மானியங்கள் மற்றும் ஆற்றுவழி வர்த்தக சாசனங்கள்', 'era': 'Pandya Classical Era', 'year_start': 800, 'year_end': 1250, 'thinai': 'marutham', 'summary_en': 'Pandya stone epigraphs from Authoor on the Tambraparni River documenting the extraordinary botanical properties, canal irrigation rights, and regional export tariffs for the legendary GI-heritage Authoor betel leaf.', 'summary_ta': 'ஆத்தூர் சோமநாத சுவாமி கோயில் கல்வெட்டுகள்; தாமிரபரணி ஆற்றுக் கால்வாய் பாசனத்தில் விளைந்த ஆத்தூர் வெற்றிலையின் சிறப்புகள் மற்றும் நெய்தல் துறைமுகங்களுக்கு அனுப்பப்பட்ட வர்த்தகத் தரவுகள்.', 'sources': ['South Indian Inscriptions Vol XIV (Pandya Inscriptions)', 'Tirunelveli District Archaeological Epigraphs', 'Marco Polo Travels (Notes on Cail and Betel Leaf Trade)'], 'content': "# Authoor Tambraparni Delta Betel Leaf Concessions & Riverine Trade Charters\n\n## 1. Historical & Geographical Setting\nAuthoor, located on the northern bank of the Tambraparni River in Thoothukudi district, is immortalized in epigraphs and traveler chronicles (including Marco Polo's account of the nearby port of Kayal) for producing the world’s most prized betel leaves. The unique alluvial soil, combined with year-round freshwater flow from the Western Ghats, gave Authoor betel leaves a distinctively sharp, spicy flavor, tender rib structure, and prolonged freshness.\n\n## 2. Riverine Trade & Concessions\n- **Canal Irrigation Rights**: Pandya royal decrees safeguarded water intake sluices from the Tambraparni weir systems, guaranteeing daily controlled flooding for betel trenches.\n- **Port Transit**: Bales of fresh Authoor leaves packed in moist banana sheaths (*Vazhai-pattai*) were ferried downriver to Korkai and Kayalpattinam for overseas export to Arabian and Southeast Asian ports.\n"}, {'slug': 'concept-betel-vine-trellis-cultivation-and-microclimate-hydrology', 'category': 'concepts', 'file': 'concept-betel-vine-trellis-cultivation-and-microclimate-hydrology.md', 'node_type': 'concept', 'name_en': 'Betel Vine Trellis Agronomy (Vetrilaik-kodi), Agathi Support Trees & Ditch Irrigation', 'name_ta': 'வெற்றிலைக் கொடிக்கால் வேளாண்மை, அகத்தி மரப் பந்தல் மற்றும் பாசன வாய்க்கால் நுட்பம்', 'era': 'Sangam to Modern Era', 'year_start': -300, 'year_end': 1900, 'thinai': 'marutham', 'summary_en': 'The sophisticated microclimate agronomy of ancient Tamil betel cultivation: establishing dense parallel raised beds, intercropping nitrogen-fixing Agathi trees as living climbing poles, and regulating humidity through flooded earthen ditches.', 'summary_ta': 'உயரமான பாத்திகளில் அகத்தி மரங்களை நட்டு, அதில் வெற்றிலைக் கொடிகளைப் படரவிட்டு, இடைப்பட்ட வாய்க்கால்களில் நீர் தேக்கி ஈரப்பதத்தைக் கட்டுப்படுத்தும் தமிழர் வேளாண் பொறியியல்.', 'sources': ['Tolkappiyam Marutham Ecology', "K.A. Nilakanta Sastri 'Studies in Chola Agrarian System'", 'Traditional Tamil Betel Horticulture Manuals'], 'content': '# Betel Vine Trellis Agronomy (Vetrilaik-kodi), Agathi Support Trees & Ditch Irrigation\n\n## 1. Horticultural Architecture: The *Kodik-kal*\nBetel (*Piper betle* / *Vetrillai*) is a shade-loving dioecious evergreen climber requiring consistent tropical warmth, high relative humidity (70–85%), and well-aerated sandy-loam soils free of waterlogging. Ancient Tamil horticulturists designed a specialized living ecosystem known as the **Kodik-kal**:\n\n1. **Raised Ridge Preparation**: Earth was mounded into narrow parallel ridges (*Varappu*) separated by deep irrigation drainage ditches (*Vaaikaal*).\n2. **Living Symbiotic Poles**: Fast-growing *Agathi* (*Sesbania grandiflora*) trees were planted along ridges. As legumes, they fixed atmospheric nitrogen into the root zone while providing a living, flexible lattice pole.\n3. **Microclimate Canopy**: Agathi foliage filtered harsh equatorial sunlight, casting dappled shade that simulated the humid forest understory.\n\n## 2. Hydrological Regulation & Training\n- **Daily Sub-Surface Inundation**: Water flowed through narrow earthen furrows, keeping root zones moist without splashing standing water onto leaves, which prevented fungal rot.\n- **Vine Pruning & Layering**: As vines grew too tall, they were untied, looped down, and partially buried in compost (*Kodi-irakkuthal*), rejuvenating root vigor and producing continuous tender flush.\n'}, {'slug': 'concept-areca-palm-harvesting-curing-and-nut-grading-metrology', 'category': 'concepts', 'file': 'concept-areca-palm-harvesting-curing-and-nut-grading-metrology.md', 'node_type': 'concept', 'name_en': 'Areca Palm Cultivation (Kamugu), Boiling Curing & Standard Nut Grading Metrology', 'name_ta': 'கமுகு பாக்கு சாகுபடி, வேகவைத்து பதப்படுத்துதல் மற்றும் பாக்கு அளவியல்', 'era': 'Sangam to Medieval Era', 'year_start': -300, 'year_end': 1400, 'thinai': 'marutham', 'summary_en': 'The plantation management of the areca nut palm (Kamugu) in ancient Tamil river basins: canopy harvesting, dehulling, boiling green nuts in herbal tannin broth (Kalli), sun-drying, and commercial sizing metrology.', 'summary_ta': 'காவிரி மற்றும் தாமிரபரணி படுகைகளில் கமுகு மரங்களிலிருந்து பாக்குகளைப் பறித்து, தோலுரித்து, துவர்ப்புச் சாற்றில் வேகவைத்து உலர்த்தி தரம் பிரிக்கும் பதப்படுத்தும் தொழில்நுட்பம்.', 'sources': ['Purananuru v. 384', 'Perumpanarruppadai ll. 350-365', 'South Indian Epigraphy: Nut Toll Records'], 'content': '# Areca Palm Cultivation (Kamugu), Boiling Curing & Standard Nut Grading Metrology\n\n## 1. Areca Cultivation (*Kamugu-thottam*)\nThe areca palm (*Areca catechu* / *Kamugu* or *Pakku-maram*) was planted alongside betel gardens and coconut groves throughout the irrigated delta tracts of ancient Tamilakam. Sangam poetry (*Perumpanarruppadai*) praises the sky-piercing trunks of *Kamugu* laden with heavy orange-red nut clusters (*Kulai*).\n\n## 2. Curing & Chemical Tannin Boiling\nRaw green areca nuts contain harsh, astringent tannins and moisture that make them unpalatable. Artisans developed a specialized hydrothermal curing process:\n- **Husking & Sectioning**: Mature semi-ripe nuts were de-husked with curved iron knives and sectioned into circular halves (*Kali-pakku*) or split quarters.\n- **Tannin Broth Boiling (*Kalli*)**: Nuts were boiled in large copper cauldrons with concentrated catechu extracts, bark tannins, and lime water for several hours to neutralize bitter alkaloids.\n- **Sun-Drying & Glaze**: The boiled nuts were spread on reed mats and sun-cured for seven days until hard, developing a glossy, deep maroon-brown coloration prized for chewing.\n'}, {'slug': 'concept-chunam-marine-shell-calcination-and-paan-alchemy', 'category': 'concepts', 'file': 'concept-chunam-marine-shell-calcination-and-paan-alchemy.md', 'node_type': 'concept', 'name_en': 'Chunam Shell Lime Calcination, Catechu Resins & Paan Chemistry (Tamboolam)', 'name_ta': 'சிப்பிச் சுண்ணாம்பு சுடுதல், காசுக்கட்டி மற்றும் தாம்பூல வேதியியல்', 'era': 'Sangam to Medieval Era', 'year_start': -200, 'year_end': 1300, 'thinai': 'neithal', 'summary_en': 'The biochemical synergy of ancient Tamil paan chewing: calcining marine bivalve shells into pure calcium hydroxide (Chunam), extracting acacia catechu resin, and catalyzing the release of arecoline alkaloids for digestion and cognitive alertness.', 'summary_ta': 'கடல் சிப்பிகளைச் சுட்டு தூய சுண்ணாம்பு தயாரித்தல், காசுக்கட்டியின் துவர்ப்பு மற்றும் வெற்றிலைச் சாற்றுடன் இணையும் போது உருவாகும் செந்நிற வேதியியலும் செரிமானப் பலன்களும்.', 'sources': ['Siddha Materia Medica on Sunnambu', 'Journal of Ethnopharmacology: Betel Quid Chemistry', 'Silappadikaram Urai on Tamboolam'], 'content': '# Chunam Shell Lime Calcination, Catechu Resins & Paan Chemistry (Tamboolam)\n\n## 1. Marine Shell Calcination (*Chunam / Sunnambu*)\nThe essential alkaline component of Tamil paan was **Chunam** (slaked lime, $Ca(OH)_2$). While stone limestone was available inland, coastal artisans collected marine mollusks, oyster shells, and pearl-chank fragments (*Chanku-sunnambu*) along the Gulf of Mannar:\n- **High-Temperature Calcination**: Shells were layered with charcoal inside small cylindrical clay kilns and fired at ~900°C to drive off $CO_2$, leaving pure white quicklime ($CaO$).\n- **Slaking & Herbal Infusion**: Quicklime was slaked with water and filtered through fine cloth, yielding a silky, non-abrasive paste infused with rosewater or kewra essence.\n\n## 2. The Chemistry of the Crimson Saliva\nWhen betel leaf (containing chavibetol and eugenol), areca nut (containing the alkaloid arecoline), and alkaline chunam combine with saliva:\n- **Alkaline Activation**: Calcium hydroxide raises oral pH, deprotonating arecoline into its lipophilic form, facilitating rapid sublingual absorption and stimulating the central nervous system.\n- **Tannin Oxidation**: Alkaline conditions oxidize areca tannins and catechu, creating the iconic brilliant crimson pigment that symbolized vitality and joy in classical Tamil society.\n'}, {'slug': 'concept-lost-wax-bronze-betel-boxes-and-royal-regalia-caskets', 'category': 'concepts', 'file': 'concept-lost-wax-bronze-betel-boxes-and-royal-regalia-caskets.md', 'node_type': 'concept', 'name_en': 'Lost-Wax Cast Bronze Betel Caskets (Pakkuk-kudai), Areca Nut Cutters & Court Regalia', 'name_ta': 'மெழுகு உருக்கு வெண்கல பாக்குக் கூடைகள், பாக்குவெட்டிகள் மற்றும் அரச அணிகலன் பேழைகள்', 'era': 'Pallava to Nayaka Era', 'year_start': 600, 'year_end': 1600, 'thinai': 'marutham', 'summary_en': 'The metallurgical artistry behind royal Tamil betel accoutrements: cire-perdue cast bell-metal and bronze betel caskets (Pakkuk-kudai), multi-tiered leaf caddies, and articulated steel areca nut cutters (Pakku-vetti) sculpted as yalis and peacocks.', 'summary_ta': 'சோழர் மற்றும் நாயக்கர் அரசவையில் வெண்கலத்தால் வார்க்கப்பட்ட கலைநயமிக்க பாக்குக் கூடைகள், பல அடுக்கு வெற்றிலைப் பேழைகள் மற்றும் யாளி வடிவ எஃகு பாக்குவெட்டிகளின் உலோகம்.', 'sources': ["C. Sivaramamurti 'South Indian Bronzes'", 'National Museum Catalog of Indian Betel Accessories', 'South Indian Inscriptions Vol II: Palace Vessels'], 'content': '# Lost-Wax Cast Bronze Betel Caskets (Pakkuk-kudai), Areca Nut Cutters & Court Regalia\n\n## 1. Courtly Metallurgy & Regal Accessories\nIn royal courts across Tamilakam, the serving of betel was accompanied by high metallurgical ostentation. Elite coppersmiths (*Kammalar*) cast elaborate bronze and brass betel chests:\n- **Pakkuk-kudai & Chellam**: Compartmentalized bronze boxes featuring fitted inner trays for fresh leaves, segmented dishes for sliced nuts, and screw-top containers for lime paste.\n- **Hinged Lids & Pierced Jali**: Lids were cast using lost-wax methods with pierced openwork (*Jali*) depicting pairs of billing doves, lotuses, or royal crests, providing ventilation to keep moist leaves fresh.\n\n## 2. Articulated Areca Nut Cutters (*Pakku-vetti*)\n- **Wootz Steel & Brass Inlay**: The levered nut-cutter was engineered with razor-sharp tempered steel jaws capable of cleanly slicing rock-hard cured areca nuts without splintering.\n- **Sculptural Handles**: Cutters were sculpted in zoomorphic motifs—intertwined yalis, galloping horses, and dancing damsels—functioning as prized courtly prestige items.\n'}, {'slug': 'char-authoor-master-betel-cultivator-vetrilai-kodi-kavalan', 'category': 'characters', 'file': 'char-authoor-master-betel-cultivator-vetrilai-kodi-kavalan.md', 'node_type': 'character', 'name_en': 'Master Betel Vine Husbandman & Trellis Hydrologist (Vetrilai-Kodi-Kavalan)', 'name_ta': 'ஆத்தூர் தலைமை வெற்றிலைக் கொடிக்கால் ஆசான் (வெற்றிலைக் கொடிக்காவலன்)', 'era': 'Pandya Classical Era', 'year_start': 850, 'year_end': 1050, 'thinai': 'marutham', 'summary_en': 'Personification of the senior horticultural elder in the Tambraparni delta at Authoor who calibrated canal inundation, selected prime runner vines, directed Agathi canopy pruning, and graded export leaf bundles.', 'summary_ta': 'தாமிரபரணி படுகையில் ஆத்தூர் கொடிக்கால்களைப் பராமரித்து, தண்ணீரின் அளவையும் நிழலின் அடர்த்தியையும் சீரமைத்து உலகத்தரம் வாய்ந்த கார வெற்றிலையை விளைவித்த வேளாண் தலைவர்.', 'sources': ['Authoor Temple Epigraphic Registers', 'Tambraparni Basin Horticultural Survey', 'Traditional Tamil Agronomy Lore'], 'content': '# Master Betel Vine Husbandman & Trellis Hydrologist (Vetrilai-Kodi-Kavalan)\n\n## 1. Biographical & Horticultural Persona\nOperating across the lush alluvial tracts of Authoor along the lower Tambraparni, the **Vetrilai-Kodi-Kavalan** represented generations of specialized agrarian wisdom. Responsible for a cooperative of twenty *kodik-kal* estates, he ensured that soil salinity, canal water temperature, and vine shading were harmonized to perfection.\n\n## 2. Technical Mastery & Trade Dispatch\n- **Runner Selection**: Propagating exclusively from vigorous two-year-old mother vines (*Thai-kodi*) to preserve genetic disease resistance.\n- **Canal Flow Modulation**: Timing ditch flooding to the morning ebb and draining excess monsoonal silt before noon to prevent fungal leaf spot.\n- **Moist Sheath Packaging**: Packing harvested leaves in layers with damp plantain bark, allowing them to travel three days by riverboat to coastal ports without losing their crisp, peppery bite.\n'}, {'slug': 'char-madurai-court-paan-master-tamboola-nayagan', 'category': 'characters', 'file': 'char-madurai-court-paan-master-tamboola-nayagan.md', 'node_type': 'character', 'name_en': 'Imperial Court Paan Master & Diplomatic Hospitality Warden (Tamboola-Nayagan)', 'name_ta': 'மதுரை அரச தாம்பூலப் பொறுப்பாளர் மற்றும் விருந்தோம்பல் தலைவர் (தாம்பூல நாயகன்)', 'era': 'Sangam to Pandya Era', 'year_start': -50, 'year_end': 250, 'thinai': 'marutham', 'summary_en': 'Archetype of the royal palace officer at Madurai charged with compounding exquisite spiced paan rolls for the monarch, ambassadors, and victorious generals, safeguarding the royal betel casket.', 'summary_ta': 'மதுரை பாண்டிய மன்னர் அரசவையில் தூதுவர்களுக்கும் தளபதிகளுக்கும் நறுமணத் தாம்பூலம் வழங்கி, அரச மரியாதையையும் ராஜதந்திர நல்லுறவையும் பேணிய தலைமை அரண்மனை அதிகாரி.', 'sources': ['Silappadikaram Commentary on Court Officers', 'Pandya Palace Inscriptions on Royal Staff', 'Purananuru v. 384 Notes'], 'content': '# Imperial Court Paan Master & Diplomatic Hospitality Warden (Tamboola-Nayagan)\n\n## 1. Courtly Function & Trust\nThe **Tamboola-Nayagan** (or *Adaikkai-kavalan*) held a position of intimate trust within the imperial royal household. Because royal assassination through poisoned food or paan was a perpetual peril in ancient statecraft, the preparation of the monarch’s personal betel quids was entrusted only to noble, sworn officers of hereditary loyalty.\n\n## 2. Diplomatic Rituals & Compounding\n- **The Spiced Quid**: Compounding thin heart-shaped leaves with precise micro-doses of crushed cardamom, powdered cloves, edible camphor (*Pachai-karpooram*), and gold leaf foil.\n- **Ratification of Honor**: Presenting the ceremonial betel plate (*Vetrilai-thambalam*) from the royal throne to seal military alliances, grant tax charters, or honor visiting tributary chieftains.\n'}, {'slug': 'place-authoor-ancient-betel-vine-groves', 'category': 'places', 'file': 'place-authoor-ancient-betel-vine-groves.md', 'node_type': 'place', 'name_en': 'Authoor Ancient Betel Vine Groves & Tambraparni Canal Basin', 'name_ta': 'ஆத்தூர் - பண்டைய வெற்றிலைக் கொடிக்கால் தோட்டங்கள் மற்றும் தாமிரபரணி படுகை', 'era': 'Pandya Classical Era', 'year_start': 700, 'year_end': 1400, 'thinai': 'marutham', 'summary_en': 'Celebrated riverine delta settlement on the Tambraparni River in southern Tamil Nadu acclaimed for centuries of cultivating the world-famous pungent Authoor betel leaf utilizing natural flood-irrigation channels.', 'summary_ta': 'தூத்துக்குடி மாவட்டத்தில் தாமிரபரணி ஆற்றங்கரையில் அமைந்துள்ள தொன்மைமிக்க மருத நிலத் தளம்; உலகப்புகழ் பெற்ற ஆத்தூர் வெற்றிலை விளையும் பாரம்பரியத் தோட்டங்களின் பிறப்பிடம்.', 'sources': ['Tirunelveli District Archaeological Survey', 'Imperial Gazetteer of India: Authoor', 'Marco Polo Travels (Cail Chapter)'], 'content': "# Authoor Ancient Betel Vine Groves & Tambraparni Canal Basin\n\n## 1. Geographical & Hydrological Excellence\nAuthoor (8.6333° N, 78.0833° E) is situated in the fertile deltaic plain of the Tambraparni River, approximately 15 kilometers inland from the historic Pandya port of Korkai. The location benefits from the nutrient-dense silt deposited by the annual monsoonal floods of the Tambraparni and a high water-table that sustains perennial microclimate humidity.\n\n## 2. Heritage Agrarian Landscape\n- **Centuries of Monoculture**: The landscape is defined by vast contiguous grids of *kodik-kal* estates crisscrossed by narrow earthen canals (*Vaaikaal*) taking water from the Marudur and Srivaikuntam anicut systems.\n- **Global Recognition**: Historical records, spanning medieval Pandya epigraphs, Arab maritime logs, and modern Geographical Indication (GI) registry, corroborate Authoor's unbroken millennial heritage as the capital of Tamil betel viticulture.\n"}, {'slug': 'text-manimekalai-potter-guild-and-terracotta-effigy-poetry', 'category': 'texts', 'file': 'text-manimekalai-potter-guild-and-terracotta-effigy-poetry.md', 'node_type': 'text', 'name_en': 'Manimekalai Potter Guild (Kuyavar), Votive Terracottas & Funerary Urn Hymns', 'name_ta': 'மணிமேகலை - குயவர் குலத் தொழிற்கூடம், சுடுமண் உருவங்கள் மற்றும் ஈமத்தாழிப் பாடல்கள்', 'era': 'Post-Sangam Classical Era', 'year_start': 200, 'year_end': 500, 'thinai': 'marutham', 'summary_en': 'Poetic descriptions in Manimekalai (Chakkaravalak-kottam and Uvavanam chapters) and Akananuru portraying skilled potters (Kuyavar / Vettakkaran) modeling clay figurines, funerary urns, and sacred guardian terracotta effigies.', 'summary_ta': 'மணிமேகலை சக்கரவாளக்கோட்டக் காதையில், சுடுமண்ணால் உயிர் போன்ற சிற்பங்களையும், பிரம்மாண்ட ஈமத்தாழிகளையும், காவல் தெய்வ உருவங்களையும் வடிக்கும் குயவர் கலையைப் போற்றும் வரிகள்.', 'sources': ['Manimekalai Chakkaravalak-kottam ll. 35-50', 'Akananuru v. 256', 'Natrinai v. 293'], 'content': '# Manimekalai: Potter Guild (Kuyavar), Votive Terracottas & Funerary Urn Hymns\n\n## 1. Classical Epic Evidence\nIn the classical Tamil Buddhist epic *Manimekalai* by Seethalai Sathanar, the cosmopolitan cemetery precinct of Poompuhar (*Chakkaravalak-kottam*) features vivid accounts of funerary pottery and votive sculptures. Potters (*Kuyavar*) are praised for their versatile clay artistry, creating giant burial urns (*Mudhumakkal-thaazhi*), anthropomorphic effigies of deities and ancestral spirits, and protective guardian beast sculptures placed at crossroads.\n\nIn *Akananuru* (v. 256), the venerable village potter (*Kalam-sey-kuyavan*) is depicted throwing clay on a heavy rotating wheel, modeling vessels and votive figurines with effortless plastic mastery.\n\n## 2. Spiritual & Cultural Resonance\n- **Earth to Form**: Clay (*Mann*) was revered as the primeval matter of creation; terracotta votives were seen as the most democratic and heartfelt devotional offerings to village deities (*Grama-devata* / *Ayyanar*).\n- **Mortuary Continuity**: Massive terracotta burial urns symbolized the womb of Mother Earth (*Puvi-thay*), returning mortal remains in an eternal cycle of death and rebirth.\n'}, {'slug': 'insc-keezhadi-terracotta-figurine-and-brahmi-epigraphs', 'category': 'inscriptions', 'file': 'insc-keezhadi-terracotta-figurine-and-brahmi-epigraphs.md', 'node_type': 'inscription', 'name_en': 'Keezhadi Excavations Anthropomorphic Terracotta Figurines & Tamil-Brahmi Epigraphs', 'name_ta': 'கீழடி - சுடுமண் மனித உருவங்கள், அணிகலன் சிற்பங்கள் மற்றும் தமிழ்-பிராமித் தரவுகள்', 'era': 'Sangam Classical Era', 'year_start': -600, 'year_end': 200, 'thinai': 'marutham', 'summary_en': 'Archaeological excavation finds from Keezhadi near Madurai revealing finely modeled anthropomorphic terracotta female heads, elaborate turbaned male figures, game pieces, and associated Tamil-Brahmi inscriptions dated to the 6th century BCE.', 'summary_ta': 'கீழடி அகழாய்வில் வெளிப்பட்ட நுட்பமான சுடுமண் பெண் தலை உருவங்கள், கொண்டை அலங்காரங்கள், சுடுமண் காதணிகள் மற்றும் 6ஆம் நூற்றாண்டு கி.மு. தமிழ்-பிராமி எழுத்துப் பொறிப்புகள்.', 'sources': ['Tamil Nadu State Department of Archaeology Keezhadi Excavation Reports', 'Amarnath Ramakrishna Archaeological Survey Memoirs', 'Radiocarbon Dating from Beta Analytic (Keezhadi 580 BCE)'], 'content': "# Keezhadi Excavations Anthropomorphic Terracotta Figurines & Tamil-Brahmi Epigraphs\n\n## 1. Archaeological Discoveries & High Antiquity\nThe landmark excavations at Keezhadi on the Vaigai riverbed, directed by the Archaeological Survey of India and the Tamil Nadu State Department of Archaeology, uncovered a sophisticated urban civilization dating back to 580 BCE.\n\nAmong the most compelling artistic finds were dozens of finely hand-modeled and molded terracotta human figurines. These figurines exhibit delicate facial features, elongated almond eyes, beaded jewelry, and extraordinarily intricate coiffures reflecting the refined urban aesthetics of ancient Madurai.\n\n## 2. Terracotta Repertoire & Typology\n- **Anthropomorphic Heads**: Distinctive terracotta female and male portraits displaying high headdresses, double hair-buns (*Kondai*), and heavy ear ornaments (*Kundalam*).\n- **Pinch-Modeled Votive Figurines**: Miniature humped bulls (*Vellai-yerudhu*), elephants, and birds used for household rituals and children's toys (*Mann-bommai*).\n- **Epigraphic Corroboration**: Inscribed potsherds discovered in identical stratigraphic layers prove widespread literacy among the artisan and merchant populace.\n"}, {'slug': 'insc-sendamangalam-potter-charters-and-ayyanar-endowments', 'category': 'inscriptions', 'file': 'insc-sendamangalam-potter-charters-and-ayyanar-endowments.md', 'node_type': 'inscription', 'name_en': 'Sendamangalam Potter Guild Tax Remissions & Ayyanar Votive Steed Charters', 'name_ta': 'சேந்தமங்கலம் - குயவர் வணிகக் குழு வரிவிலக்கு மற்றும் அய்யனார் குதிரை அறக்கொடை சாசனங்கள்', 'era': 'Medieval Chola to Kadava Era', 'year_start': 1200, 'year_end': 1300, 'thinai': 'mullai', 'summary_en': 'Kadava Chieftain Kopperunjinga stone inscriptions at Sendamangalam recording tax remissions for village potter guilds (Kuyavar-kadamai) in exchange for sculpting monumental terracotta war horses for rural Ayyanar shrines.', 'summary_ta': 'காடவ மன்னன் காடவன் கோப்பெருஞ்சிங்கனின் சேந்தமங்கலக் கல்வெட்டுகள்; கிராமத்துக் காவல் அய்யனார் கோயில்களுக்கு சுடுமண் குதிரைகளை நேர்த்தியாக வடித்து வழங்கிய குயவர்களுக்கு வழங்கப்பட்ட நில மானியங்கள்.', 'sources': ['South Indian Inscriptions Vol VIII (Kadava Inscriptions)', 'Sendamangalam Archaeological Survey', 'Journal of Epigraphical Society of India'], 'content': '# Sendamangalam Potter Guild Tax Remissions & Ayyanar Votive Steed Charters\n\n## 1. Kadava Dynasty Patronage of Rural Shrines\nAt Sendamangalam (Villupuram district), the capital of the 13th-century Kadava ruler Kopperunjinga I, epigraphs shed unique light on the institutional support granted to village ceramic sculptors (*Kuyap-perun-thatchan*).\n\nWhile royal stone temples received monumental granite gopurams, rural and agrarian protector shrines (*Ayyanar / Sastha* and *Pidari* shrines) were endowed with monumental terracotta votive statuary.\n\n## 2. Inscriptional Covenants & Responsibilities\n- **Tax Remission (*Kuyavan-kaani*)**: Potters were granted hereditary rent-free agricultural lands (*Kani*) and exemption from state clay levies.\n- **Votive Equine Quotas**: In return, the potter guild pledged to sculpt and fire life-sized or colossal terracotta horses (*Kudhirai-eduppu*) complete with molded reins, saddle cloths, and warrior escorts, dedicating them during annual village festivals.\n'}, {'slug': 'concept-hollow-coil-construction-monumental-terracotta-horses', 'category': 'concepts', 'file': 'concept-hollow-coil-construction-monumental-terracotta-horses.md', 'node_type': 'concept', 'name_en': 'Monumental Ayyanar Votive Horses, Hollow Coil Modeling & Granular Clay Physics', 'name_ta': 'அய்யனார் பிரம்மாண்ட சுடுமண் குதிரைகள், உள்ளீடற்ற புரிசுருள் கட்டமைப்பு மற்றும் களிமண் இயற்பியல்', 'era': 'Sangam to Modern Era', 'year_start': -300, 'year_end': 1900, 'thinai': 'mullai', 'summary_en': 'The extraordinary ceramic engineering of building colossal hollow terracotta horses (often exceeding 15 feet): utilizing hollow-cylinder coil building, internal clay baffle arches, grog temper, and slow-fire moisture vents.', 'summary_ta': '15 அடிக்கும் மேலான உயரமான அய்யனார் சுடுமண் குதிரைகளை வெடிப்பின்றி உருவாக்க, உள்ளீடற்ற புரிசுருள் நுட்பம், உள்வளைவுத் தாங்கு அமைப்புகள் மற்றும் களிமண் சுடு பொறியியல்.', 'sources': ["Stephen P. Huyler 'Gifts of Earth: Terracottas & Clay Sculptures of India'", "Pupul Jayakar 'The Earth Mother'", 'Tamil Nadu Folk Ceramic Arts Survey'], 'content': '# Monumental Ayyanar Votive Horses, Hollow Coil Modeling & Granular Clay Physics\n\n## 1. Structural Engineering of Colossal Terracotta\nTamil Nadu boasts the largest hollow terracotta sculptures in the world: the monumental votive horses (*Kudhirai*) offered to Ayyanar, village guardian deity of field tanks and boundaries. Reaching heights from 6 to over 15 feet, these sculptures require mastery of structural engineering and ceramic physics to prevent collapse under their own weight during construction and firing:\n\n1. **Sectional Coil Construction**: Rather than solid modeling, the limbs, torso, and neck are built up in modular hollow cylinders using thick coils of clay.\n2. **Internal Diaphragms & Arches**: Hollow clay baffle plates and horizontal diaphragms are integrated across the chest and barrel to act as load-bearing rib arches.\n3. **Moisture Vent Holes**: Small concealed perforations are pierced through the ears, nostrils, and saddle folds to allow trapped interior moisture and steam to vent during firing, preventing explosive fractures.\n\n## 2. Grog Tempering & Surface Appliqué\n- **Anti-Shrinkage Grog**: Local river tank clay (*Kalam-mann*) is tempered with 25–30% crushed terracotta shards (*grog*), fine quartz sand, and chopped straw to minimize drying shrinkage and thermal shock.\n- **Molded Appliqué Ornamentation**: Flamboyant harness bells, chest garlands, fly-whisks, and guardian riders (*Veeran*) are hand-pressed in wooden molds and luted to the leather-hard torso using liquid clay slip (*Kadal*).\n'}, {'slug': 'concept-megalithic-burial-urn-pyrotechnics-and-black-and-red-reduction', 'category': 'concepts', 'file': 'concept-megalithic-burial-urn-pyrotechnics-and-black-and-red-reduction.md', 'node_type': 'concept', 'name_en': 'Megalithic Funerary Urns (Mudhumakkal-thaazhi), Slip Pyrotechnics & Reduction Firing', 'name_ta': 'பெருங்கற்கால ஈமத்தாழிகள், மெழுகூட்டல் மற்றும் தலைகீழ் குறைப்புச் சூளை நுட்பம்', 'era': 'Iron Age to Sangam Era', 'year_start': -1000, 'year_end': 200, 'thinai': 'kurinji', 'summary_en': 'The pyrotechnic production of massive pear-shaped burial urns (Mudhumakkal-thaazhi) in Iron Age and Sangam Tamilakam: paddle-and-anvil thinning, iron-oxide slip burnishing, and inverted reduction firing producing Black-and-Red Ware.', 'summary_ta': 'பெருங்கற்காலத் தமிழகத்தில் தட்டுப்பலகை கொண்டு அடித்து உருவாக்கப்பட்ட பிரம்மாண்ட ஈமத்தாழிகள்; இரும்பு ஆக்சைடு பூச்சு மற்றும் காற்றுப் புகாத் தலைகீழ் குறைப்புச் சூளை மூலம் கருப்பு-சிவப்பு வண்ணம் பெறுதல்.', 'sources': ['ASI Excavation Reports: Adichanallur (Rea 1904, Sathyamurthy 2004)', "K. Rajan 'Iron Age Culture in Tamil Nadu'", 'Journal of Archaeological Science: BRW Pyrotechnology'], 'content': '# Megalithic Funerary Urns (Mudhumakkal-thaazhi), Slip Pyrotechnics & Reduction Firing\n\n## 1. Funerary Urn Geometry & Throwing (*Mudhumakkal-thaazhi*)\nExcavated by the thousands at Adichanallur, Porunthal, and Keezhadi, the giant megalithic burial urns represent an apex of manual ceramic potting:\n- **Paddle-and-Anvil Expansion (*Thattal*)**: A thick-walled hollow conical blank thrown on a slow wheel was expanded to full capacity (up to 1.5 meters height and 1 meter diameter) using a wooden paddle (*Thattuk-kattai*) on the outside and a polished stone anvil (*Kallu*) held against the interior.\n- **Reinforced Heavy Rims**: Massive rolled rims were engineered to withstand the crushing overhead pressure of megalithic stone capstones and soil overburden.\n\n## 2. Inverted Firing & Black-and-Red Ware (BRW)\n- **Inverted Kiln Placement**: The urns and associated companion bowls were loaded upside-down into the kiln.\n- **Reducing Interior**: Organic matter (rice husks, cow dung) placed inside the inverted vessels created a carbon monoxide-rich reducing atmosphere, precipitating carbon nanoparticles and converting ferric oxide ($Fe_2O_3$) into lustrous black magnetite ($Fe_3O_4$).\n- **Oxidizing Exterior**: The outer body, exposed to draft oxygen, oxidized to brilliant terracotta brick-red, creating the classical bicolored Black-and-Red ware.\n'}, {'slug': 'concept-anthropomorphic-terracotta-figurines-and-hair-bun-stylistics', 'category': 'concepts', 'file': 'concept-anthropomorphic-terracotta-figurines-and-hair-bun-stylistics.md', 'node_type': 'concept', 'name_en': 'Anthropomorphic Terracotta Figurines, Pinch-Modeling & Classical Sangam Coiffures', 'name_ta': 'சுடுமண் மனிதச் சிற்பங்கள், கை-அழுத்து வடிவமைப்பு மற்றும் சங்ககாலக் கூந்தல் அலங்காரங்கள்', 'era': 'Sangam Classical Era', 'year_start': -500, 'year_end': 200, 'thinai': 'marutham', 'summary_en': 'The plastic sculptural technique of ancient Tamil anthropomorphic terracotta figurines: combining hollow molded facial masks with hand-pinched torsos, detailing ornate multi-tiered coiffures (Kondai), ear studs, and necklaces.', 'summary_ta': 'சுடுமண்ணில் அச்சுகள் மற்றும் கை-அழுத்து நுட்பங்களை இணைத்து, சங்க இலக்கியங்கள் கூறும் ஐம்பால் கூந்தல் அலங்காரங்கள் மற்றும் காதணிகளுடன் செதுக்கப்பட்ட மனித உருவச் சிற்பங்கள்.', 'sources': ['Keezhadi Archaeological Reports Vols 1-3', "Champakalakshmi 'Iconography in Early Tamil Nadu'", 'Marg: Terracotta Art of South India'], 'content': '# Anthropomorphic Terracotta Figurines, Pinch-Modeling & Classical Sangam Coiffures\n\n## 1. Dual Modeling Techniques\nAncient Tamil terracotta figurines excavated across the Vaigai and Kaveri valleys reflect a synthesis of press-molding and hand-sculpting:\n- **Press-Molded Facials**: Finely engraved terracotta negative molds were used to press out uniform, exquisite facial masks with sharp aquiline noses and arched eyebrows.\n- **Hand-Pinched & Coil Bodies**: Torsos, limbs, and clothing folds were modeled freehand and fused with the molded head using slip while clay was in the plastic state.\n\n## 2. Sangam Hair Styling (*Aimpaal*) & Jewelry\nThe figurines serve as a primary physical archive of ancient Tamil personal adornment:\n- **Fivefold Hair Buns (*Aimpaal*)**: Terracotta female heads depict the five classical coiffure styles celebrated in Sangam poetry: *Kuzhal*, *Alagam*, *Kondai*, *Panichai*, and *Mudichu*, adorned with molded floral wreaths (*Kanni*).\n- **Ear Flares (*Kundalam / Olai*)**: Massive cylindrical terracotta ear plugs and disc flares that expanded the earlobes, matching excavated terracotta ear spools.\n'}, {'slug': 'concept-open-clamp-bonfire-kilns-and-rice-husk-reduction', 'category': 'concepts', 'file': 'concept-open-clamp-bonfire-kilns-and-rice-husk-reduction.md', 'node_type': 'concept', 'name_en': 'Open Clamp Bonfire Kilns (Soolai), Rice-Husk Smothering & Smoke Impregnation', 'name_ta': 'திறந்த தரைச் சூளைகள் (சூளை), உமி மூட்டம் மற்றும் புகை அடைப்பு எரிப்பு நுட்பம்', 'era': 'Sangam to Modern Era', 'year_start': -400, 'year_end': 1800, 'thinai': 'marutham', 'summary_en': 'The rural firing pyrotechnology of Tamil potter communities: constructing temporary open clamp kilns (Soolai) using stacked green pots, fuel layering with palmyra fronds and rice husks, and controlled earth smothering for reduction.', 'summary_ta': 'மட்கலங்கள் மற்றும் சுடுமண் சிற்பங்களை திறந்த தரையில் அடுக்கிக் கூட்டி, உமி, வைக்கோல் மற்றும் பனை மட்டைகளை வைத்து மண் மூடி சீராகச் சுடும் பாரம்பரியச் சூளை முறை.', 'sources': ["Achaya & Saraswati 'Pottery Techniques in Peasant India'", 'Tamil Lexicon: Soolai', 'Ethno-archaeology of Southern Indian Potters'], 'content': '# Open Clamp Bonfire Kilns (Soolai), Rice-Husk Smothering & Smoke Impregnation\n\n## 1. The Architecture of the *Soolai*\nIn traditional Tamil pottery villages, permanent brick updraft kilns were rare; instead, potters utilized modular open clamp bonfires known as **Soolai**:\n1. **Conical Vessel Stacking**: Sun-dried pots, jars, and terracotta figurines were stacked in a circular pyramid over a bottom hearth grate of thick firewood logs.\n2. **Fuel Interleaving**: Spaces between vessels were packed with slow-burning, high-carbon fuels: rice husks (*Umi*), dry cattle dung cakes (*Varatti*), and palmyra leaf stalks (*Panang-kattai*).\n3. **Earth Thatching & Mud Plastering**: The entire mound was thatched with straw and sealed with a layer of wet mud, leaving small bottom draft holes and a central crown chimney.\n\n## 2. Firing Cycle & Reduction Control\n- **Slow Dehydration Phase**: A slow smoky fire was maintained for 12 hours to drive off chemically bound water without cracking green clay.\n- **Peak Vitrification (800°C–900°C)**: Air holes were opened, igniting intense combustion that vitrified clay minerals into durable ceramic.\n- **Smothering for Lustrous Black**: For reduction blackware, the chimney and vents were suddenly sealed with damp earth at peak temperature; trapped carbon smoke permeated the porous clay matrix, rendering it jet-black.\n'}, {'slug': 'char-vilangudi-master-terracotta-sculptor-kuyap-perun-thatchan', 'category': 'characters', 'file': 'char-vilangudi-master-terracotta-sculptor-kuyap-perun-thatchan.md', 'node_type': 'character', 'name_en': 'Master Terracotta Votive Sculptor & Ayyanar Horse Modeler (Kuyap-Perun-Thatchan)', 'name_ta': 'விளங்குடி தலைமை சுடுமண் சிற்பி மற்றும் அய்யனார் குதிரை ஆசான் (குயப் பெருந்தச்சன்)', 'era': 'Medieval Pandya to Nayaka Era', 'year_start': 1100, 'year_end': 1350, 'thinai': 'marutham', 'summary_en': 'Personification of the senior master ceramic sculptor at Vilangudi on the Vaigai who engineered colossal hollow-coil Ayyanar votive steeds, prepared sacred tank clay batches, and presided over communal clamp firings.', 'summary_ta': 'வைகைக் கரையில் விளங்குடி பட்டறையில் பிரம்மாண்ட சுடுமண் குதிரைகளையும் காவல் தெய்வங்களையும் உள்ளீடற்ற புரிசுருள் நுட்பத்தில் வெடிப்பின்றி உருவாக்கிய தலைமைக் குயவப் பெருந்தச்சன்.', 'sources': ['Madurai District Inscriptions on Kuyavar Guilds', 'Vaigai Valley Ethno-archaeology Memoirs', 'Traditional Guild Charters of Southern Potters'], 'content': '# Master Terracotta Votive Sculptor & Ayyanar Horse Modeler (Kuyap-Perun-Thatchan)\n\n## 1. Guild Leadership & Hereditary Mastery\nOperating in the artisan quarter of Vilangudi along the Vaigai River northwest of Madurai, the **Kuyap-Perun-Thatchan** was an elite master of monumental ceramic sculpture. Revered both as an engineer and ritual officiant, he was summoned by agrarian village assemblies (*Ur*) across the Pandya country to sculpt colossal guardian steeds for regional Ayyanar groves (*Kavu*).\n\n## 2. Technical Prowess & Communal Leadership\n- **Clay Maturation**: Sourcing pristine fine clay from deep lakebeds, aging it under damp jute mats for months to enhance natural bacterial plasticity.\n- **Coil Synchronization**: Guiding teams of four apprentice sculptors in simultaneously layering balanced coils on life-sized horse legs so the clay dried evenly without structural tilting.\n- **The Sacred Firing**: Officiating the lighting of the community clamp kiln (*Soolai*), reading the smoke color to determine the precise moment to seal the air vents.\n'}, {'slug': 'char-adichanallur-funerary-urn-potter-thaazhi-kuyavan', 'category': 'characters', 'file': 'char-adichanallur-funerary-urn-potter-thaazhi-kuyavan.md', 'node_type': 'character', 'name_en': 'Master Megalithic Burial Urn Potter & Reduction Firing Specialist (Thaazhi-Kuyavan)', 'name_ta': 'ஆதிச்சநல்லூர் ஈமத்தாழி தலைமை குயவர் மற்றும் சூளை நிபுணர் (தாழிக் குயவன்)', 'era': 'Iron Age to Sangam Era', 'year_start': -800, 'year_end': -500, 'thinai': 'kurinji', 'summary_en': 'Archetype of the ancient megalithic potter at Adichanallur on the Tambraparni who expanded massive pear-shaped burial urns using stone anvils, coated them in hematite slips, and executed bicolored reduction firings.', 'summary_ta': 'ஆதிச்சநல்லூர் இடுகாட்டில் தட்டுப்பலகையும் கல்லும் கொண்டு பிரம்மாண்ட ஈமத்தாழிகளை அடித்து விரித்து, கருப்பு-சிவப்பு வண்ணத்தில் குறைப்புச் சூளையில் சுட்ட பெருங்கற்காலக் குயவர்.', 'sources': ['Adichanallur Excavation Memoirs (Alexander Rea 1904)', "K. Rajan 'Archaeology of Iron Age Tamilakam'", 'Tolkappiyam on Kalam-sey-kuyavan'], 'content': '# Master Megalithic Burial Urn Potter & Reduction Firing Specialist (Thaazhi-Kuyavan)\n\n## 1. Ancient Metallurgical & Mortuary Horizon\nWorking along the gravel terraces of Adichanallur overlooking the Tambraparni River, the **Thaazhi-Kuyavan** produced the giant ceramic burial urns that housed the chieftains, warriors, and matriarchs of Iron Age Tamilakam. His craft demanded immense physical stamina and deep understanding of thermal expansion to throw and paddle vessels large enough to contain an adult human skeleton alongside wootz iron swords and bronze vessels.\n\n## 2. Masteries of Anvil Expansion & Fire\n- **Anvil Rhythms**: Rapidly paddling wet clay against an interior stone anvil with musical precision to expand thin, uniform walls that would not collapse under their own weight.\n- **Hematite Burnishing**: Rubbing the damp exterior with crushed red hematite pebbles and animal fat to produce a waterproof, glossy red slip.\n- **Inverted Oxygen Deprivation**: Placing companion bowls inverted inside the urn during firing to produce the diagnostic Black-and-Red ware finish.\n'}, {'slug': 'place-vilangudi-ancient-terracotta-votive-haven', 'category': 'places', 'file': 'place-vilangudi-ancient-terracotta-votive-haven.md', 'node_type': 'place', 'name_en': 'Vilangudi Ancient Terracotta Votive Haven & Vaigai Potter Quarter', 'name_ta': 'விளங்குடி - பண்டைய சுடுமண் சிற்பத் தொழிற்பட்டறை மற்றும் வைகை குயவர் குடியிருப்பு', 'era': 'Sangam to Nayaka Era', 'year_start': -300, 'year_end': 1700, 'thinai': 'marutham', 'summary_en': 'Historic artisan and ceramic manufacturing settlement on the Vaigai River near Madurai celebrated for continuous millennia of crafting monumental Ayyanar terracotta votive steeds, ritual vessels, and sculptural effigies.', 'summary_ta': 'மதுரை அருகே வைகை ஆற்றங்கரையில் அமைந்துள்ள வரலாற்று சிறப்புமிக்க மட்கலைத் தளம்; அய்யனார் கோயில்களுக்கான பிரம்மாண்ட சுடுமண் குதிரைகள் வடிப்பதில் பெயர் பெற்ற தொன்மையான குயவர் குடியிருப்பு.', 'sources': ['Madurai District Gazetteer', 'Archaeological Survey of Tamil Nadu Vaigai Basin', "Stephen Huyler 'Gifts of Earth'"], 'content': '# Vilangudi Ancient Terracotta Votive Haven & Vaigai Potter Quarter\n\n## 1. Riverine Setting & Alluvial Resources\nVilangudi (9.9510° N, 78.0920° E) lies on the northern bank of the Vaigai River, immediately upstream from the historic walled city of Madurai. Its location was strategically dictated by the immense beds of plastic alluvial clay (*Kalam-mann*) deposited by the Vaigai and proximity to abundant firewood from the scrub jungles of the Madurai plains.\n\n## 2. Millennial Ceramic Heritage\n- **Continuous Industrial Continuity**: From Sangam times through the Pandya, Chola, and Nayaka periods, Vilangudi served as the primary ceramic production and sculptural quarter for greater Madurai.\n- **Ayyanar Equine Center**: The village kilns specialized in the iconic giant terracotta votive horses, elephants, and village guardian deities that were paraded with drums to sacred groves across the southern Tamil countryside.\n'}, {'slug': 'text-pattinappalai-painted-cotton-cloth-chithira-aadai-poetry', 'category': 'texts', 'file': 'text-pattinappalai-painted-cotton-cloth-chithira-aadai-poetry.md', 'node_type': 'text', 'name_en': 'Pattinappalai Painted Cotton Cloth (Chithira-Aadai) & Export Textile Hymns', 'name_ta': 'பட்டினப்பாலை - சித்திர ஆடை, பலவண்ண அச்சு ஆடைகள் மற்றும் ஏற்றுமதி நெசவுக் கவிதைகள்', 'era': 'Sangam Classical Era', 'year_start': -200, 'year_end': 200, 'thinai': 'marutham', 'summary_en': 'Classical verses in Pattinappalai (lines 100-115) and Silappadikaram celebrating finely woven cotton fabrics painted and printed with vivid floral motifs, mythical beasts, and geometrical borders known as Chithira-Aadai.', 'summary_ta': 'பட்டினப்பாலை மற்றும் சிலப்பதிகாரத்தில் காவிரிப்பூம்பட்டினத் துறைமுகத்திலிருந்து கடல்வழியாக ஏற்றுமதி செய்யப்பட்ட பலவண்ணச் சித்திர ஆடைகள், மலர் உருவங்கள் மற்றும் ஓவியத் துணிகளின் அழகைப் போற்றும் பாடல்கள்.', 'sources': ['Pattinappalai ll. 100-115', 'Silappadikaram Kadaladukkadhai ll. 85-98', 'Nedunalvadai ll. 140-150'], 'content': "# Pattinappalai: Painted Cotton Cloth (Chithira-Aadai) & Export Textile Hymns\n\n## 1. Classical Sangam Literary Evidence\nIn *Pattinappalai* (lines 100–115), poet Kadiyalur Uruttirangannanar portrays the opulent emporium of Kaveripattinam, where international merchant fleets loaded bales of fine cotton cloth stamped and painted with pictorial narratives, known in Tamil as **Chithira-Aadai** ('painted/figured garments').\n\nIn *Silappadikaram* (Kadaladukkadhai lines 85–98), court dancers and royal courtiers don exquisite diaphanous muslins adorned with resist-printed lotus medallions, geometric borders (*Kodi-karai*), and vibrant vegetable dyestuffs that retained their brilliance through repeated washing.\n\n## 2. Textile Mastery & Maritime Commerce\n- **Fine Calico & Muslin Ground**: The fabric ground was woven from gossamer-thin combed cotton yarn, bleached to dazzling whiteness using riverine washing and sun-curing.\n- **Trans-Oceanic Export**: Ancient Tamil painted calicos and resist-dyed chintz were shipped across the Bay of Bengal to the courts of Southeast Asia and westward to the Roman Empire, where they were prized above gold.\n"}, {'slug': 'insc-kodali-karuppur-chola-textile-printer-charters', 'category': 'inscriptions', 'file': 'insc-kodali-karuppur-chola-textile-printer-charters.md', 'node_type': 'inscription', 'name_en': 'Kodali Karuppur Imperial Chola Resist-Wax Textile Guild & Temple Canopy Charters', 'name_ta': 'கோடாலி கருப்பூர் - சோழர் மெழுகு அச்சு ஆடை வணிகக் குழு மற்றும் விதான அறக்கொடை சாசனங்கள்', 'era': 'Medieval Chola Era', 'year_start': 980, 'year_end': 1150, 'thinai': 'marutham', 'summary_en': 'Chola temple inscriptions from the Kaveri delta near Kumbakonam documenting royal charters granted to the specialized master textile printers of Kodali Karuppur who manufactured resist-wax dyed canopies (Meykatti) and royal court sarees.', 'summary_ta': 'கும்பகோணம் அருகே கோடாலி கருப்பூர் நெசவுக் கலைஞர்களுக்கு சோழ மன்னர்கள் வழங்கிய சாசனங்கள்; மெழுகு அச்சுப் பதிப்பு மூலம் கோயில்களுக்கான விதானங்களையும், அரச குடும்பத்தினருக்கான சேலைகளையும் உருவாக்கிய வரலாறு.', 'sources': ['South Indian Inscriptions Vol XXIII (Kumbakonam & Environs)', 'Chola Epigraphic Records on Royal Weavers', "R. Champakalakshmi 'Trade and Urbanization in Chola Times'"], 'content': '# Kodali Karuppur Imperial Chola Resist-Wax Textile Guild & Temple Canopy Charters\n\n## 1. The Heritage of Kodali Karuppur\nKodali Karuppur, situated on the northern bank of the Kollidam River near Kumbakonam, was the celebrated center of a unique hybrid textile art that fused gold-thread (*Zari*) Jamdani weaving with hot-wax resist block printing and natural dyeing.\n\nInscriptions of Rajaraja I and Rajendra I document the royal patronage lavished on the master printers (*Chithira-Achariyan*) of Karuppur, who supplied ceremonial canopies (*Meykatti* / *Melkatti*) and royal hangings for the Brihadisvara and Gangaikondacholapuram temples.\n\n## 2. Inscriptional Concessions & Guild Honors\n- **Tari-Irai Exemption**: The weaving and printing looms (*Tari*) of Kodali Karuppur were granted tax remissions in exchange for supplying annual quotas of hand-printed altar canopies.\n- **Royal Title Conferments**: Master dyers and block carvers were conferred titles such as *Tribhuvana-Chithira-Kammalan*, acknowledging their status alongside royal temple sthapatis.\n'}, {'slug': 'insc-kanchipuram-kalamkari-dyer-and-printer-guild-charters', 'category': 'inscriptions', 'file': 'insc-kanchipuram-kalamkari-dyer-and-printer-guild-charters.md', 'node_type': 'inscription', 'name_en': 'Kanchipuram Kalamkari Artisan Guilds, Alum Charters & Export Tax Epigraphs', 'name_ta': 'காஞ்சிபுரம் - கலம்காரி கைவினைஞர் குழுக்கள், படிகார சாசனங்கள் மற்றும் ஏற்றுமதி வரித் தரவுகள்', 'era': 'Pallava to Chola Era', 'year_start': 700, 'year_end': 1200, 'thinai': 'marutham', 'summary_en': 'Stone inscriptions at Kanchipuram detailing the municipal organization of textile dyers (Vannakkaran), alum mordant allocations, river washing ghat rights along the Vegavathi, and overseas export customs duties.', 'summary_ta': 'காஞ்சிபுரம் கல்வெட்டுகளில் பதிவாகியுள்ள சாயத் தொழில் வணிகர் சங்கங்கள், வேகவதி ஆற்றுக் கரையில் துணி வெளுக்கும் உரிமைகள், படிகாரக் கொள்முதல் மற்றும் ஏற்றுமதி வரிகள்.', 'sources': ['South Indian Inscriptions Vol IV & XII (Kanchipuram)', "C. Minakshi 'Administration and Social Life under the Pallavas'", 'Epigraphia Indica Vol III'], 'content': '# Kanchipuram Kalamkari Artisan Guilds, Alum Charters & Export Tax Epigraphs\n\n## 1. The Silk & Painted Cotton Capital of Thondaimandalam\nAs the imperial capital of the Pallavas and later a premier Chola viceregal metropolis, Kanchipuram developed an expansive textile ecosystem. Beyond its famous silk looms, the city housed powerful corporate guilds of cotton dyers and hand-painters, known in epigraphy as the **Pattunool-karar** and **Vannak-kudiyar**.\n\nInscriptions around the Kailasanatha and Vaikunta Perumal temples record detailed regulations regarding the allocation of water rights along the Vegavathi River for cloth bleaching and mordant fixing.\n\n## 2. Alum Mordanting & Fiscal Epigraphy\n- **Alum Procurement Charters**: Inscriptions record state-managed supplies of natural alum (*Padi-karam* / potassium aluminum sulfate) imported from mineral deposits to bind red madder dyes.\n- **Customs Levies (*Ulgu*)**: Finished bales of figured cloth (*Chithira-pudavai*) transported via the Palar River to the port of Mamallapuram were assessed standard export customs duties recorded on temple stone tablets.\n'}, {'slug': 'concept-carved-teakwood-printing-blocks-and-relief-geometry', 'category': 'concepts', 'file': 'concept-carved-teakwood-printing-blocks-and-relief-geometry.md', 'node_type': 'concept', 'name_en': 'Carved Hardwood Printing Blocks (Achchu-maram), Teak Mortising & Repeating Geometry', 'name_ta': 'செதுக்கப்பட்ட மர அச்சுப் பலகைகள் (அச்சுமரம்), தேக்குக் குடைவு மற்றும் வடிவியல் அச்சு முறை', 'era': 'Sangam to Medieval Era', 'year_start': -200, 'year_end': 1400, 'thinai': 'marutham', 'summary_en': 'The woodcarving engineering of textile printing blocks (Achchu-maram): precision relief gouging into seasoned teak or rosewood, registering alignment pin marks, and carving interlocking geometric and floral repeating patterns.', 'summary_ta': 'பதப்படுத்தப்பட்ட தேக்கு மற்றும் ஈட்டி மரங்களில் உளிகளைக் கொண்டு மலர் மற்றும் வடிவியல் உருவங்களை புடைப்பாகச் செதுக்கி, துணியில் துல்லியமாகப் பதிக்கும் அச்சுமரப் பொறியியல்.', 'sources': ['Traditional Indian Textile Printing Technology (Gittinger)', "Kamaladevi Chattopadhyay 'Handicrafts of India'", 'South Indian Wood Carving Technical Bulletins'], 'content': '# Carved Hardwood Printing Blocks (Achchu-maram), Teak Mortising & Repeating Geometry\n\n## 1. Wood Selection & Seasoning for Textile Blocks\nThe fidelity of ancient Tamil block printing depended upon the dimensional stability of the wooden printing matrix (*Achchu-maram*). Artisans selected high-density, close-grained hardwoods:\n- **Teak (*Thekku*) & Rosewood (*Eetti*)**: Naturally saturated with resins and oils, resisting water swelling, acid mordants, and repetitive impact without splitting.\n- **Oil Seasoning**: Carved blocks were soaked in mustard or sesame oil for several weeks to prevent ink absorption and ensure clean release of dye pastes.\n\n## 2. Relief Carving & Registration Mechanics\n- **Deep Background Relief**: Negative areas were chiseled away to a depth of 5–8 mm using wootz steel gouges to prevent stray ink deposits on cloth.\n- **Air Release Channels**: Narrow drill holes were bored through the back of the block into deep design recesses to release air pockets, ensuring continuous, unbroken dye transfer.\n- **Registration Pin Markers (*Kani-kole*)**: Corner registration notches allowed printers to align multi-color block impressions (outline, background, filler) with millimeter accuracy across lengths of cloth.\n'}, {'slug': 'concept-molten-beeswax-resist-application-and-crackling-textures', 'category': 'concepts', 'file': 'concept-molten-beeswax-resist-application-and-crackling-textures.md', 'node_type': 'concept', 'name_en': 'Molten Beeswax Resist Application, Freehand Kalam Pens & Crackling Dye Resist', 'name_ta': 'உருகிய தேன்மெழுகு அச்சுப் பூச்சு, கலம் பேனா வரைதல் மற்றும் மெழுகு விரிசல் சாயத் தடுப்பு', 'era': 'Sangam to Medieval Era', 'year_start': -300, 'year_end': 1300, 'thinai': 'marutham', 'summary_en': 'The chemistry and application of molten beeswax-resin resists in ancient Tamil textile arts: utilizing freehand bamboo kalam pens and carved wooden blocks, followed by cold dye vat immersion and deliberate wax crackling.', 'summary_ta': 'தேன்மெழுகையும் மரப் பிசினையும் உருக்கி, மூங்கில் கலம் மற்றும் மர அச்சு மூலம் துணியில் பூசி, சாயக் குளியலில் நனைத்து, மெழுகை உடைத்து மெல்லிய விரிசல் வண்ணக் கோடுகளை உருவாக்கும் கலை.', 'sources': ['Silappadikaram Commentary on Chithira-Aadai', "Mattiebelle Gittinger 'Master Dyers to the World'", 'Journal of Indian Textile History'], 'content': '# Molten Beeswax Resist Application, Freehand Kalam Pens & Crackling Dye Resist\n\n## 1. The Resist Formulation: Wax and Resin Chemistry\nIn the resist-dyeing tradition of ancient Tamilakam, molten wax served as an impermeable barrier against cold aqueous dye solutions:\n- **Compounded Resist**: Pure forest beeswax (*Theyn-mezhugu*) was blended with **dammar resin** (*Guggu / Kungiliyam*) and a fraction of castor oil. The resin elevated the melting point to prevent bleeding under tropical ambient temperatures, while the oil imparted elasticity.\n- **The Freehand Kalam**: For narrative canopies, draughtsmen used the **Kalam**—a pointed bamboo reed wrapped in a ball of absorbent wool string that acted as a continuous reservoir for molten wax.\n\n## 2. Immersion & Deliberate Crackling (*Veeral-kann*)\n- **Cold Vat Immersion**: Waxed cloth was gently dipped into cold indigo or madder vats; the wax blocked dye penetration, preserving pristine white ground beneath.\n- **Controlled Crackling**: Before dyeing, the waxed fabric was deliberately crumpled in cold water. Micro-fractures formed across the brittle wax, allowing fine hair-like veins of dye to seep through, producing the celebrated organic crackle texture (*Veeral-kann*).\n- **Dewaxing in Boiling Water**: Following dyeing, the cloth was submerged in boiling water; the molten wax floated to the surface, where it was skimmed off and recycled for future batches.\n'}, {'slug': 'concept-iron-acetate-fermented-rust-black-dye-kasik-kattu', 'category': 'concepts', 'file': 'concept-iron-acetate-fermented-rust-black-dye-kasik-kattu.md', 'node_type': 'concept', 'name_en': 'Fermented Iron Acetate (Kasi-k-kattu), Jaggery Rust Chemistry & Fast Black Inks', 'name_ta': 'இரும்பு துரு நொதிப்புச் சாயம் (காசிக்கட்டு), வெல்லக் கரைசல் வேதியியல் மற்றும் கறுப்பு மை', 'era': 'Sangam to Modern Era', 'year_start': -300, 'year_end': 1900, 'thinai': 'marutham', 'summary_en': 'The natural biochemical formulation of ancient Tamil permanent black printing ink (Kasi-k-kattu / Karuppu): fermenting rusted scrap iron with palm jaggery, toddy vinegar, and myrobalan tannins to yield jet-black ferric gallate.', 'summary_ta': 'பழைய இரும்புத் துண்டுகளை கரும்பு வெல்லம் மற்றும் கள்ளு வினிகருடன் மண்பானையில் பல வாரங்கள் நொதிக்க வைத்து, கடுக்காய் சாற்றுடன் இணைத்து அழியாத கறுப்புச் சாயத்தை உருவாக்கும் முறை.', 'sources': ["Achaya 'Indigenous Chemical Arts of Southern India'", 'Siddha Chemistry: Rasavatham and Dye Formulations', 'Traditional Kalamkari Craft Manuals'], 'content': '# Fermented Iron Acetate (Kasi-k-kattu), Jaggery Rust Chemistry & Fast Black Inks\n\n## 1. Fermentation Chemistry of *Kasi-k-kattu*\nAncient Tamil textile printers and scribes produced one of the most chemically permanent black inks of antiquity: **Kasi-k-kattu** (fermented iron acetate):\n1. **The Fermentation Stew**: Scrap wootz iron shavings, rusted nails, and horseshoe trimmings were loaded into a large earthen pot.\n2. **Organic Acid Medium**: A solution of water, sugarcane jaggery (*Vellam*), and fermented palm toddy (*Kallu*) was poured over the iron.\n3. **Acetate Synthesis**: Over 21 days of anaerobic fermentation, acetic acid and lactic acid synthesized by wild yeasts attacked the metallic iron, converting it into soluble ferrous acetate ($Fe(CH_3COO)_2$).\n\n## 2. Reaction with Myrobalan Tannins\n- **Cloth Tannin Priming**: Before printing, cotton cloth was treated with an extract of crushed *Kadukkai* (chebulic myrobalan / *Terminalia chebula*), depositing gallotannins into the fiber cellulose.\n- **Ferric Gallate Precipitation**: When the fermented iron liquid was stamped or painted onto the cloth, the ferrous ions reacted instantly with the gallotannins, precipitating water-insoluble, light-fast **ferric gallate**—a permanent, pitch-black bond that never washed out or faded in sunlight.\n'}, {'slug': 'concept-riverine-running-water-washing-and-sun-bleaching-science', 'category': 'concepts', 'file': 'concept-riverine-running-water-washing-and-sun-bleaching-science.md', 'node_type': 'concept', 'name_en': 'Riverine Continuous Flow Washing, Sheep Dung Bleaching & Sun-Curing Fixation', 'name_ta': 'ஆற்றுநீர் ஓட்டக் கழுவுதல், ஆட்டுச்சாண வெளுப்பு முறை மற்றும் சூரிய ஒளி நிலைநிறுத்தல்', 'era': 'Sangam to Medieval Era', 'year_start': -300, 'year_end': 1400, 'thinai': 'marutham', 'summary_en': 'The ecological and biochemical washing regimen of ancient Tamil textile centers: harnessing continuous flowing Kaveri river water, alkaline sheep dung enzymes for non-destructive bleaching, and photochemical solar fixation.', 'summary_ta': 'காவிரி போன்ற வற்றாத ஆறுகளின் தூய நீரில் துணிகளை அலசுதல், ஆட்டுச்சாண என்சைம்கள் கொண்டு நூலிழைக்கு பாதிப்பின்றி வெளுத்தல் மற்றும் சூரிய ஒளியில் வண்ணங்களை நிலைநிறுத்தும் அறிவியல்.', 'sources': ['Pattinappalai Text & Commentaries', 'Journal of the Textile Association of India', 'Traditional Indian Dyeing Protocols'], 'content': '# Riverine Continuous Flow Washing, Sheep Dung Bleaching & Sun-Curing Fixation\n\n## 1. The Role of Running River Water\nThe production of brilliant printed cottons required vast volumes of mineral-free, flowing freshwater. The Kaveri and Tambraparni rivers were internationally famed for their soft waters, which carried optimal mineral balances (low in iron and calcium carbonates) that prevented unwanted mud-staining or premature mordant precipitation.\n\nSpecialized riverside bleaching sectors (*Salavai-thurai*) were reserved exclusively for textile guilds.\n\n## 2. Organic Bleaching & Photochemical Fixation\n- **Enzymatic Bleaching with Dung**: Raw grey cotton contains natural pectin, waxes, and seed coats. Artisans soaked cloth in an emulsion of water and fresh sheep or cow dung. Natural digestive enzymes (cellulases, proteases) gently digested fiber impurities without weakening the cellulose backbone.\n- **Solar Photolysis**: The treated cloth was stretched across clean river sandbars in the scorching equatorial sun. Continually sprinkled with water, ultraviolet radiation reacted with atmospheric oxygen to generate singlet oxygen and hydroxyl radicals, bleaching the cloth to pristine optic whiteness.\n- **Sun-Baking of Mordants**: After madder and indigo dyeing, sun-curing on hot sand catalyzed coordination bonding between metallic aluminum ions and alizarin chromophores, ensuring permanent wash-fastness.\n'}, {'slug': 'char-kodali-karuppur-master-block-printer-chithira-achariyan', 'category': 'characters', 'file': 'char-kodali-karuppur-master-block-printer-chithira-achariyan.md', 'node_type': 'character', 'name_en': 'Master Resist-Wax Block Printer & Royal Canopy Artisan (Chithira-Achariyan)', 'name_ta': 'கோடாலி கருப்பூர் தலைமை அச்சு ஆசான் மற்றும் அரச விதான கலைஞர் (சித்திர ஆசாரியன்)', 'era': 'Medieval Chola Era', 'year_start': 1000, 'year_end': 1150, 'thinai': 'marutham', 'summary_en': 'Personification of the senior master textile printer at Kodali Karuppur who combined waxy resist printing with Jamdani gold-thread brocades, managing imperial commissions for royal temple canopies and Chola court regalia.', 'summary_ta': 'கோடாலி கருப்பூர் நெசவுக் கூடத்தில் மெழுகு அச்சுப் பதிப்பையும் பொன்நூல் ஜரிகையையும் இணைத்து, சோழ மன்னர்களுக்கும் தஞ்சைப் பெருங்கோயிலுக்கும் விதானங்களை வடித்த தலைமைச் சித்திர ஆசாரியன்.', 'sources': ['Brihadisvara Temple Fabric Inventory Epigraphs', 'Chola Royal Weaver Charters', 'Karuppur Textile Guild Tradition'], 'content': '# Master Resist-Wax Block Printer & Royal Canopy Artisan (Chithira-Achariyan)\n\n## 1. Guild Leadership & Imperial Office\nBased at Kodali Karuppur on the northern banks of the Kollidam River, the **Chithira-Achariyan** held the prestigious royal title of Imperial Textile Designer to the Chola crown. His atelier was entrusted with executing the magnificent ceremonial ceiling canopies (*Melkatti*) under which Rajaraja I and Rajendra I sat during state durbars and victory celebrations.\n\n## 2. Technical Mastery & Hybrid Virtuosity\n- **Synchronizing Weave and Print**: Pre-planning Jamdani gold-thread bands on the loom so that subsequent wax-resist block stamps nestled perfectly into geometric warp windows.\n- **Thermal Wax Formulations**: Modulating the proportion of dammar resin in the wax bath according to seasonal ambient temperatures (dry summer vs. damp northeast monsoon).\n- **Quality Inspection**: Scrutinizing the edge sharpness of printed mordant lines under natural morning light, ensuring zero dye-bleeding into pure white cotton fields.\n'}, {'slug': 'char-kanchipuram-master-mordant-dyer-kalam-evar', 'category': 'characters', 'file': 'char-kanchipuram-master-mordant-dyer-kalam-evar.md', 'node_type': 'character', 'name_en': 'Master Freehand Kalam Draughtsman & Mineral Mordant Chemist (Kalam-Evar)', 'name_ta': 'காஞ்சிபுரம் தலைமை கலம்காரி ஓவியர் மற்றும் படிகாரச் சாய ஆசான் (கலம்-ஏவர்)', 'era': 'Pallava to Chola Era', 'year_start': 750, 'year_end': 950, 'thinai': 'marutham', 'summary_en': 'Archetype of the master freehand Kalam draughtsman at Kanchipuram who drew intricate epics and botanical scrolls onto bleached cotton using bamboo pens, alum mordants, and fermented iron black inks.', 'summary_ta': 'காஞ்சிபுரத்தில் வேகவதி ஆற்றங்கரையில் மூங்கில் கலம் கொண்டு இராமாயண-மகாபாரதக் காட்சிகளைப் படிகாரக் கரைசலாலும் இரும்பு மையாலும் வரைந்து சாயமிட்ட தலைமை ஓவிய ஆசிரியர்.', 'sources': ['Kanchipuram Temple Epigraphs on Temple Hangings', "C. Minakshi 'Pallava Crafts'", 'Kalamkari Artisan Heritage Oral Traditions'], 'content': '# Master Freehand Kalam Draughtsman & Mineral Mordant Chemist (Kalam-Evar)\n\n## 1. The Art of the Freehand *Kalam*\nStationed within the sacred temple quarters of Kanchipuram along the Vegavathi River, the **Kalam-Evar** (or *Chithira-karan*) was a master artist-chemist. Unlike repetitive block printers, he specialized in monumental narrative temple hangings (*Thombai* / *Kalamkari*) that illustrated mythic cycles for religious processions.\n\nUsing a pointed bamboo reed pen wrapped in wool, he drew sweeping fluid outlines directly onto tannin-primed cotton cloth with steady, unhesitating grace.\n\n## 2. Chemical Mastery of Mordants\n- **Differential Mordanting**: Applying concentrated alum paste where vivid crimson madder was desired, diluted alum for soft pink, and fermented iron acetate (*Kasi-k-kattu*) for permanent black outlines.\n- **The Madder Boiling Crucible**: Submerging the drawn cloth into boiling vats of crushed *Chaya-ver* (chay-root / *Oldenlandia umbellata*); like magic, colors developed only where the chemical mordants had been drawn, leaving un-mordanted areas spotless white.\n'}, {'slug': 'place-kodali-karuppur-ancient-textile-printing-haven', 'category': 'places', 'file': 'place-kodali-karuppur-ancient-textile-printing-haven.md', 'node_type': 'place', 'name_en': 'Kodali Karuppur Ancient Textile Printing Haven & Kaveri Riverbank Bleaching Grounds', 'name_ta': 'கோடாலி கருப்பூர் - பண்டைய துணி அச்சுத் தொழிற்பட்டறை மற்றும் காவிரி சலவைக் கரைகள்', 'era': 'Medieval Chola Era', 'year_start': 900, 'year_end': 1500, 'thinai': 'marutham', 'summary_en': 'Historic textile artisan settlement near Kumbakonam on the Kollidam River renowned for royal Chola resist-wax block printing, hybrid gold Jamdani sarees, and extensive riverbank bleaching sandbars.', 'summary_ta': 'கும்பகோணம் அருகே கொள்ளிடக் கரையில் அமைந்துள்ள வரலாற்றுப் புகழ் பெற்ற ஆடை அச்சு மையம்; மெழுகு அச்சு, இயற்கைச் சாயங்கள் மற்றும் அரச குடும்ப சேலைகள் தயாரிப்பில் புகழ்பெற்ற தளம்.', 'sources': ['South Indian Inscriptions Vol XXIII', 'Kumbakonam Regional Gazetteer', 'Traditional Crafts Survey: Karuppur Textiles'], 'content': '# Kodali Karuppur Ancient Textile Printing Haven & Kaveri Riverbank Bleaching Grounds\n\n## 1. Topography & Riverine Setting\nKodali Karuppur (11.0833° N, 79.3333° E) is situated in the fertile deltaic fork where the Kaveri branches into the Kollidam River in Thanjavur district. The village was intentionally developed by Chola monarchs as a designated royal craft enclave, taking advantage of the vast, clean sandbars (*Manal-thittu*) along the Kollidam for sun-bleaching and continuous running water for rinsing mordanted fabrics.\n\n## 2. Unique Textile Specialization\n- **The Karuppur Saree & Canopy**: The settlement was the sole manufacturing center of the legendary *Karuppur style*—cotton cloth brocaded with gold *zari* motifs on the loom and subsequently hand-stamped with resist-wax patterns and dyed in deep madder red and fermented black.\n- **Ecological Infrastructure**: The riverbanks were lined with stone washing ramps, wooden boiling vats, and shaded drying sheds that supported a guild of over three hundred specialized weavers, printers, and dyers.\n'}]

